            if (roundIdx === 1) return isEs ? this.BOOST_LABELS_ES : this.BOOST_LABELS_EN;
            if (roundIdx === 2) return isEs ? this.RESTR_LABELS_ES : this.RESTR_LABELS_EN;
            return isEs ? this.EXIT_LABELS_ES : this.EXIT_LABELS_EN;
