        _updateTechBars(ds) {
            var techs = [
                { bar: 'laBar', val: 'laCapDisplay', cap: ds.leadAcidCap || 95 },
                { bar: 'liBar', val: 'liCapDisplay', cap: ds.lionCap || 0 },
