        validateDecisions(decisions) {
            var s = parseInt(document.getElementById('sustainingInput').value) || 0;
            var l = parseInt(document.getElementById('lionInput').value) || 0;
            var f = parseInt(document.getElementById('lfpInput').value) || 0;
            var ss = parseInt(document.getElementById('solidStateInput').value) || 0;
            var total = s + l + f + ss;

            if (total !== 100) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('alloc_warning'), 'warning'
                );
                return false;
            }

            decisions.sustainingPct = s;
            decisions.lionPct = l;
            decisions.lfpPct = f;
            decisions.solidStatePct = ss;

            var stratEl = document.getElementById('strategySelect');
            if (stratEl) decisions.strategyChoice = parseInt(stratEl.value);
            var secEl = document.getElementById('secondarySelect');
            if (secEl) decisions.secondaryChoice = parseInt(secEl.value);

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;

            var rdBudget = ds.rdBudget;
            var orgIdx = (ds.orgStructure || 1) - 1;
            if (round === 1) {
                orgIdx = d.strategyChoice - 1;
                ds.orgStructure = d.strategyChoice;
                ds.partnerType = d.secondaryChoice;
                var pIdx = d.secondaryChoice - 1;
                ds.lionCap += this.PARTNER_CAP_LION[pIdx];
                ds.lfpCap += this.PARTNER_CAP_LFP[pIdx];
                ds.cash -= this.PARTNER_COST[pIdx];
            }

            var boostAmount = 0;
            if (round === 2) {
                boostAmount = this.BOOST_AMOUNT[(d.secondaryChoice || 1) - 1];
                ds.cash -= boostAmount;
            }

            var totalRd = rdBudget + boostAmount;
            var sustInv = totalRd * (d.sustainingPct / 100);
            var lionInv = totalRd * (d.lionPct / 100);
            var lfpInv = totalRd * (d.lfpPct / 100);
            var ssInv = totalRd * (d.solidStatePct / 100);

            var orgMultD = this.ORG_MULT_DISRUPTIVE[orgIdx] || 0.55;
            var orgMultS = this.ORG_MULT_SUSTAINING[orgIdx] || 1.0;

            var sustGain = (sustInv / this.TECH_COST.sustaining) * orgMultS * 0.35;
            var lionGain = (lionInv / this.TECH_COST.lion) * orgMultD * 2.8;
            var lfpGain = (lfpInv / this.TECH_COST.lfp) * orgMultD * 2.8;
            var ssGain = (ssInv / this.TECH_COST.solidState) * orgMultD * 2.5;

            ds.leadAcidCap = Math.min(100, ds.leadAcidCap + sustGain);
            ds.lionCap = Math.min(100, ds.lionCap + lionGain);
            ds.lfpCap = Math.min(100, ds.lfpCap + lfpGain);
            ds.solidStateCap = Math.min(100, ds.solidStateCap + ssGain);

            var eventMsg = '';
            var evt = this.EVENTS[round - 1];
            if (evt && Math.random() < evt.prob) {
                eventMsg = this._isEs() ? evt.es : evt.en;
                if (evt.lionBonus) ds.lionCap = Math.min(100, ds.lionCap + evt.lionBonus);
                if (evt.lfpBonus) ds.lfpCap = Math.min(100, ds.lfpCap + evt.lfpBonus);
                if (evt.ssBonus) ds.solidStateCap = Math.min(100, ds.solidStateCap + evt.ssBonus);
                if (evt.marginHit) ds.priceCollapse = true;
                if (evt.acquisitionOffer) ds.acquisitionOffered = true;
                if (round === 1) ds.evSubsidyActive = true;
                if (round === 2) ds.voltaAccelerated = true;
            }
            ds.eventLog = eventMsg;

            var baseAutoRev = 182 * 0.58;
            var baseIndRev = 182 * 0.28;
            var baseDeepRev = 182 * 0.14;
            var growthFactor = 1 + (round * 0.025);

            if (round >= 2) {
                var indThreshold = 40;
                if (ds.evSubsidyActive) indThreshold = 35;
                var bestIndCap = Math.max(ds.lionCap, ds.lfpCap);
                if (bestIndCap < indThreshold) {
                    var indLoss = Math.min(60, (indThreshold - bestIndCap) * 1.8);
                    ds.industrialMarketShare = Math.max(40, ds.industrialMarketShare - indLoss);
                } else {
                    ds.industrialMarketShare = Math.min(100, ds.industrialMarketShare + 2);
                }
                if (d.strategyChoice === 2 && round === 2) {
                    ds.industrialMarketShare = Math.min(100, ds.industrialMarketShare + 8);
                    ds.cash -= 4;
                }
            }

            if (round >= 3) {
                var autoThreshold = 60;
                if (ds.evSubsidyActive) autoThreshold = 55;
                if (ds.lionCap < autoThreshold) {
                    var autoLoss = Math.min(55, (autoThreshold - ds.lionCap) * 1.3);
                    ds.autoMarketShare = Math.max(25, ds.autoMarketShare - autoLoss);
                } else {
                    ds.autoMarketShare = Math.min(100, ds.autoMarketShare - 5 + (ds.lionCap - autoThreshold) * 0.5);
                }
                if (round === 3) {
                    if (d.strategyChoice === 2) {
                        ds.autoMarketShare = Math.max(10, ds.autoMarketShare - 20);
                        ds.industrialMarketShare = Math.min(100, ds.industrialMarketShare + 10);
                    } else if (d.strategyChoice === 3) {
                        ds.deepCycleMarketShare = Math.min(120, ds.deepCycleMarketShare + 15);
                    } else if (d.strategyChoice === 4) {
                        ds.cash += 15;
                    }
                }
                if (round === 3 && d.secondaryChoice >= 2) {
                    var restrBonus = [0, 0.08, 0.15, 0.22];
                    var restrCost = [0, 3, 7, 14];
                    orgMultD = Math.min(1.2, orgMultD + restrBonus[d.secondaryChoice - 1]);
                    ds.cash -= restrCost[d.secondaryChoice - 1];
                }
            }

            if (round === 4) {
                if (d.strategyChoice === 1) {
                    ds.autoMarketShare = Math.max(20, ds.autoMarketShare - 10);
                    ds.leadAcidCap = Math.min(100, ds.leadAcidCap + 3);
                } else if (d.strategyChoice === 2) {
                    ds.autoMarketShare = Math.max(20, ds.autoMarketShare - 3);
                } else if (d.strategyChoice === 3) {
                    ds.autoMarketShare = Math.max(10, ds.autoMarketShare - 8);
                    ds.lionCap = Math.min(100, ds.lionCap + 5);
                    ds.lfpCap = Math.min(100, ds.lfpCap + 5);
                    ds.solidStateCap = Math.min(100, ds.solidStateCap + 3);
                }
                if (ds.acquisitionOffered && d.secondaryChoice === 1) {
                    ds.cash += 280;
                    eventMsg += (eventMsg ? '<br>' : '') + (this._isEs() ? 'Adquisición completada: COP 280B recibidos.' : 'Acquisition completed: COP 280B received.');
                    ds.eventLog = eventMsg;
                }
            }

            if (ds.priceCollapse) {
                growthFactor *= 0.82;
            }

            var laAutoRev = baseAutoRev * (ds.autoMarketShare / 100) * growthFactor;
            var laIndRev = baseIndRev * (ds.industrialMarketShare / 100) * growthFactor;
            var laDeepRev = baseDeepRev * (ds.deepCycleMarketShare / 100) * growthFactor;
            ds.leadAcidRevenue = Math.round(laAutoRev + laIndRev + laDeepRev);

            var newTechMarketBase = 30 * round;
            var lionRev = ds.lionCap > 25 ? (ds.lionCap / 100) * newTechMarketBase * 0.5 : 0;
            var lfpRev = ds.lfpCap > 25 ? (ds.lfpCap / 100) * newTechMarketBase * 0.35 : 0;
            var ssRev = ds.solidStateCap > 35 ? (ds.solidStateCap / 100) * newTechMarketBase * 0.25 : 0;
            ds.newTechRevenue = Math.round(lionRev + lfpRev + ssRev);

            ds.revenue = ds.leadAcidRevenue + ds.newTechRevenue;
            ds.newTechPct = ds.revenue > 0 ? Math.round((ds.newTechRevenue / ds.revenue) * 100) : 0;

            var totalAutoInd = ds.autoMarketShare * 0.58 + ds.industrialMarketShare * 0.28 + ds.deepCycleMarketShare * 0.14;
            ds.coreMarketShare = Math.round(totalAutoInd);

            var ebitdaMargin = 0.182;
            if (ds.priceCollapse) ebitdaMargin = 0.14;
            var ebitda = ds.revenue * ebitdaMargin;
            var rdSpend = totalRd;
            ds.cash += ebitda - rdSpend;
            ds.cash = Math.round(ds.cash * 10) / 10;

            ds.rdBudget = Math.round(ds.revenue * 0.046 * 10) / 10;
            ds.rdEfficiency = ds.rdBudget > 0 ? Math.round((ds.revenue / (ds.rdBudget * round)) * 100) / 100 : 1;

            ds.revenueHistory.push(ds.revenue);
            ds.leadAcidRevHistory.push(ds.leadAcidRevenue);
            ds.newTechRevHistory.push(ds.newTechRevenue);
            ds.marketShareHistory.push(ds.coreMarketShare);
            ds.lionCapHistory.push(Math.round(ds.lionCap));
            ds.lfpCapHistory.push(Math.round(ds.lfpCap));
            ds.ssCapHistory.push(Math.round(ds.solidStateCap));

            // same weighted total as getPerformanceSummary (max 1000), scaled by 10 to a 0-100 platform score
            var scoreX = 0;
            scoreX += Math.min(300, (ds.revenue / 220) * 300);
            scoreX += Math.min(250, (ds.coreMarketShare / 65) * 250);
            scoreX += Math.min(250, (ds.newTechPct / 25) * 250);
            var rdEffX = ds.revenue > 0 ? ds.revenue / (182 * 0.046 * 4) : 1;
            scoreX += Math.min(200, (rdEffX / 1.8) * 200);
            var overallScoreX = Math.max(0, Math.min(100, Math.round(scoreX / 10)));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScoreX });

            var results = {
                period: round,
                revenue: ds.revenue,
                leadAcidRevenue: ds.leadAcidRevenue,
                newTechRevenue: ds.newTechRevenue,
                newTechPct: ds.newTechPct,
                coreMarketShare: ds.coreMarketShare,
                autoMarketShare: Math.round(ds.autoMarketShare),
                industrialMarketShare: Math.round(ds.industrialMarketShare),
                lionCap: Math.round(ds.lionCap),
                lfpCap: Math.round(ds.lfpCap),
                solidStateCap: Math.round(ds.solidStateCap),
                cash: ds.cash,
                event: eventMsg
            };

            // v1.1.0 P0 FIX: render next round's briefing/options synchronously. Old setTimeout
            // fired AFTER the framework incremented state.currentPeriod, so (currentPeriod + 1)
            // overshot by one and showed round N+2's briefing/strategy options for rounds 2+.
            // Pre-increment here, currentPeriod is still N so (N + 1) is the correct next round.
            this._updateBriefing({ currentPeriod: state.currentPeriod + 1, domainState: ds });

            return results;
        }

