            uiManager.bind('cashDisplay', 'domainState.cash',
                (v) => 'COP ' + (Math.round(v * 10) / 10).toLocaleString() + 'B');

            // v1.1.0 FIX: framework Undo restores state/KPIs but not this sim's briefing/options/bars.
            // Re-render the restored round (deferred, after the framework undo handler).
            var self = this;
            var undoBtn = document.getElementById('undoBtn');
            if (undoBtn) {
                undoBtn.addEventListener('click', function() {
                    setTimeout(function() {
                        if (window.mySimulation && window.mySimulation.state) {
                            self._updateBriefing(window.mySimulation.state);
                        }
                    }, 0);
                });
            }
        }

